#!/usr/bin/env pwsh
# Generated by `espalier render-script`; edits are lost on the next render.
$ErrorActionPreference = 'Stop'

if (-not $env:ESPALIER_ELASTICSEARCH_URL) {
    Write-Error 'ESPALIER_ELASTICSEARCH_URL must be set'
    exit 1
}
$ElasticsearchUrl = $env:ESPALIER_ELASTICSEARCH_URL.TrimEnd('/')
$ElasticsearchAuth = $null
if ($env:ESPALIER_ELASTICSEARCH_API_KEY) {
    $ElasticsearchAuth = "ApiKey $env:ESPALIER_ELASTICSEARCH_API_KEY"
}

if (-not $env:ESPALIER_KIBANA_URL) {
    Write-Error 'ESPALIER_KIBANA_URL must be set'
    exit 1
}
$KibanaUrl = $env:ESPALIER_KIBANA_URL.TrimEnd('/')

function Invoke-EsPut {
    param([string]$Path, [string]$Body)
    $headers = @{ 'Content-Type' = 'application/json' }
    if ($ElasticsearchAuth) { $headers['Authorization'] = $ElasticsearchAuth }
    try {
        Invoke-RestMethod -Method Put -Uri "$ElasticsearchUrl$Path" -Headers $headers -Body $Body | Out-Null
    } catch {
        Write-Error "PUT $Path failed: $($_.Exception.Message)"
        exit 1
    }
}

function Test-Healthy {
    try {
        $health = Invoke-RestMethod -Method Get -Uri "$ElasticsearchUrl/_cluster/health"
    } catch {
        return $false
    }
    if ($health.status -ne 'green' -and $health.status -ne 'yellow') {
        return $false
    }
    if ($KibanaUrl) {
        try {
            $status = Invoke-RestMethod -Method Get -Uri "$KibanaUrl/api/status"
        } catch {
            return $false
        }
        if ($status.status.overall.level -ne 'available') {
            return $false
        }
    }
    return $true
}

function Wait-Healthy {
    $deadline = (Get-Date).AddSeconds(30)
    while ($true) {
        if (Test-Healthy) { return }
        if ((Get-Date) -ge $deadline) {
            Write-Error 'target not healthy within 30s'
            exit 1
        }
        Start-Sleep -Milliseconds 250
    }
}

function Invoke-KibanaPost {
    param([string]$Path, [string]$Body)
    $headers = @{ 'kbn-xsrf' = 'true'; 'Content-Type' = 'application/json' }
    if ($ElasticsearchAuth) { $headers['Authorization'] = $ElasticsearchAuth }
    try {
        Invoke-RestMethod -Method Post -Uri "$KibanaUrl$Path" -Headers $headers -Body $Body | Out-Null
    } catch {
        Write-Error "POST $Path failed: $($_.Exception.Message)"
        exit 1
    }
}

function Invoke-KibanaImport {
    param([string]$Ndjson)
    $headers = @{ 'kbn-xsrf' = 'true' }
    if ($ElasticsearchAuth) { $headers['Authorization'] = $ElasticsearchAuth }
    $tempFile = Join-Path ([System.IO.Path]::GetTempPath()) ([System.IO.Path]::GetRandomFileName() + '.ndjson')
    Set-Content -Path $tempFile -Value $Ndjson -Encoding utf8 -NoNewline
    try {
        $response = Invoke-RestMethod -Method Post -Uri "$KibanaUrl/api/saved_objects/_import?overwrite=true" -Headers $headers -Form @{ file = Get-Item $tempFile }
    } catch {
        Write-Error "kibana import failed: $($_.Exception.Message)"
        exit 1
    } finally {
        Remove-Item -Path $tempFile -Force -ErrorAction SilentlyContinue
    }
    if ($response.success -eq $false) {
        Write-Error "kibana import reported failures: $($response | ConvertTo-Json -Depth 10 -Compress)"
        exit 1
    }
}

Wait-Healthy

